package domain.config

import domain.engine.{LightRole, PaletteType, RGB}
import pureconfig.ConfigReader
import pureconfig.error.CannotConvert

/** How the `light-show` section of the config file is read, rejecting settings that can't work. */
object LightShowConfigReaders {

  given ConfigReader[PaletteType] = ConfigReader[String].emap { name =>
    PaletteType.parse(name).toRight(CannotConvert(name, "PaletteType", s"expected one of ${PaletteType.names.keys.toList.sorted.mkString(", ")}"))
  }

  given ConfigReader[BeatSource] = ConfigReader[String].emap { name =>
    BeatSource.parse(name).toRight(CannotConvert(name, "BeatSource", "expected spotify or audio"))
  }

  given ConfigReader[LightRole] = ConfigReader[String].emap { name =>
    LightRole.parse(name).toRight(CannotConvert(name, "LightRole", "expected rhythm, colour or pulse"))
  }

  given ConfigReader[RGB] = ConfigReader[String].emap { hex =>
    RGB.fromHex(hex).toRight(CannotConvert(hex, "RGB", "expected a colour like #1e1408"))
  }

  given ConfigReader[PulseSettings] = ConfigReader.derived[PulseSettings]
  given ConfigReader[PauseSettings] = ConfigReader.derived[PauseSettings]
  given ConfigReader[AudioSettings] = ConfigReader.derived[AudioSettings]
  given ConfigReader[SwellSettings] = ConfigReader.derived[SwellSettings]
  given ConfigReader[RhythmSettings] = ConfigReader.derived[RhythmSettings]
  given ConfigReader[ReactiveSettings] = ConfigReader.derived[ReactiveSettings]

  given ConfigReader[LightShowConfig] = ConfigReader.derived[LightShowConfig].emap { c =>
    LightShowConfig.validate(c).left.map(reason => CannotConvert("light-show", "LightShowConfig", reason))
  }
}

package beat

import domain.config.RhythmSettings

/** Calms the kick pattern for the rhythm lights: weak sixteenths dropped, close kicks merged, strength steadied. */
object Calm {

  /** Below this strength the kicks have dropped out, and the smoothed strength follows them at once. */
  val DropOut: Double = 0.4

  /** While smoothing, a strength below this shows as rest. */
  val Resting: Double = 0.15

  /** How far the strength may move in a bar at smoothing 0.5; it scales with (1 - s) / s. */
  val StepPerBar: Double = 0.08

  /** The pattern to play: `levels` thresholded, scaled by `strength` and spaced at least `minGapMs` apart at `bpm`. */
  def pattern(levels: Vector[Double], strength: Double, settings: RhythmSettings, bpm: Double): Vector[Double] = ???

  /** 0 up to `t`, then rising to 1 at the loudest: (v - t) / (1 - t). */
  def threshold(level: Double, t: Double): Double = ???

  /** The fewest sixteenths at `bpm` that are at least `minGapMs` long; at least 1. */
  def gapSteps(minGapMs: Long, bpm: Double): Int = ???

  /**
   * Lit sixteenths fewer than `gap` apart, around the bar, merged into one on the group's first, as strong as its
   * strongest. Grouping starts after the longest unlit run; a last group too close to the bar's first joins the one before.
   */
  def spaced(pattern: Vector[Double], gap: Int): Vector[Double] = ???

  /** The strength after one more sixteenth heard, moving towards `playing` no faster than `smoothing` allows. */
  def follow(strength: Double, playing: Double, smoothing: Double): Double = ???

  /** The strength the lights show: rest below [[Resting]] while smoothing. */
  def shown(strength: Double, smoothing: Double): Double = ???
}

package beat

import domain.config.RhythmSettings

/**
 * The kick pattern of a bar: how hard the kick drum's range hits on each sixteenth of a four-beat bar. It's learnt
 * along the beat grid, so the lights can play it back on time, ahead of each hit, instead of reacting to hits after
 * they're heard.
 *
 * `shape` averages each sixteenth over the last several bars, which is steady enough to show the pattern; `recent`
 * over the last bar or two, which shows whether it's still being played. `usualLift` is how far the pattern usually
 * stands out, `learnt` how many sixteenths have been heard, and `step` the one being heard now, counted along the grid,
 * with the `sum` and `count` of the kick power heard in it so far. `strength` is how hard the kicks are playing,
 * smoothed from bar to bar (see [[Calm.follow]]).
 */
case class Groove(
  shape: Vector[Double],
  recent: Vector[Double],
  usualLift: Double,
  learnt: Long,
  step: Long,
  sum: Double = 0.0,
  count: Int = 0,
  strength: Double = 0.0
) {

  /** Moves on to `beats` beats into the grid, having just heard `kick` power in the kick drum's range. */
  def at(beats: Double, kick: Double, smoothing: Double = 0.0): Groove = {
    val now = Groove.stepAt(beats)
    if (now <= step) copy(sum = sum + kick, count = count + 1)
    else {
      // The step just finished learns what was heard in it; any skipped over (the grid can jump) learn nothing.
      val heard = Option.unless(count == 0)(sum / count)
      val learning = heard.fold(this) { power =>
        val slot = Groove.slot(step)
        val bars = learnt / Groove.Steps
        def learn(values: Vector[Double], rate: Double) =
          values.updated(slot, values(slot) + math.max(rate, 1.0 / (bars + 1)) * (power - values(slot)))
        val nextRecent = learn(recent, Groove.RecentRate)
        val usual = usualLift + math.max(Groove.UsualRate, 1.0 / (learnt + 1)) * (Groove.lift(nextRecent) - usualLift)
        copy(shape = learn(shape, Groove.ShapeRate), recent = nextRecent, usualLift = usual, learnt = learnt + 1)
      }
      learning.copy(step = now, sum = kick, count = 1)
    }
  }

  /**
   * How strongly each sixteenth of the bar is played, from 0 to 1: the loudest is 1 and anything no louder than the
   * typical sixteenth is 0. While the kicks are quieter than usual, or gone, the whole pattern fades with them. Until
   * a full bar has been heard, a plain kick on every beat.
   */
  def pattern: Vector[Double] =
    if (learnt < Groove.Steps) Groove.Prior
    else {
      val sorted = shape.sorted
      val middle = sorted(Groove.Steps / 2)
      val lift = sorted.last - middle
      val playing = if (usualLift <= 1e-12) 0.0 else math.min(1.0, Groove.lift(recent) / usualLift)
      if (lift <= 1e-12) Vector.fill(Groove.Steps)(0.0)
      else shape.map(v => math.max(0.0, math.min(1.0, (v - middle) / lift)) * playing)
    }

  /** Each sixteenth's level between the bar's typical sixteenth (0) and its loudest (1), before the kicks' strength. */
  def levels: Vector[Double] = ???

  /** How hard the kicks are playing now compared with usual, from 0 to 1. */
  def playing: Double = ???

  /** [[pattern]] calmed by `settings` at `bpm` (see [[Calm.pattern]]); the plain kick on every beat until a bar is learnt. */
  def calm(settings: RhythmSettings, bpm: Double): Vector[Double] = ???
}

object Groove {
  val BeatsPerBar: Int = 4
  val StepsPerBeat: Int = 4
  val Steps: Int = BeatsPerBar * StepsPerBeat

  /** How much one bar changes the pattern's shape: it settles over six or seven bars. */
  val ShapeRate: Double = 0.15

  /** How much one bar changes the recent pattern: a bar or two without kicks shows. */
  val RecentRate: Double = 0.5

  /** How much one sixteenth changes how far the pattern usually stands out: about ten bars. */
  val UsualRate: Double = 0.006

  /** A plain kick on every beat. */
  val Prior: Vector[Double] = Vector.tabulate(Steps)(i => if (i % StepsPerBeat == 0) 1.0 else 0.0)

  /** A fresh groove at `beats` beats into the grid. */
  def start(beats: Double): Groove =
    Groove(Vector.fill(Steps)(0.0), Vector.fill(Steps)(0.0), 0.0, 0L, stepAt(beats))

  /** The sixteenth nearest to `beats` beats into the grid, so a kick slightly ahead of the grid counts as on it. */
  def stepAt(beats: Double): Long = math.round(beats * StepsPerBeat)

  def slot(step: Long): Int = Math.floorMod(step, Steps.toLong).toInt

  /** How far the loudest sixteenth stands above the typical one. */
  def lift(values: Vector[Double]): Double = {
    val sorted = values.sorted
    sorted.last - sorted(Steps / 2)
  }
}
